function tsToEpoch(input, ms){
  if(input===null||input===undefined||input==='') return { error:'请输入时间戳或日期' };
  var s=String(input).trim();
  if(/^\d+$/.test(s)){
    var v=Number(s);
    return { error:null, epoch:v, ms: ms || (s.length>11) };
  }
  var iso=s.replace(' ','T');
  if(!/Z$/.test(iso) && !/[+\-]\d{2}:?\d{2}$/.test(iso)) iso+='Z';
  var d=new Date(iso);
  if(isNaN(d.getTime())) return { error:'无法解析日期：'+s };
  return { error:null, epoch:Math.floor(d.getTime()/1000), ms: ms || false };
}
function tsFromEpoch(epoch, ms){
  var d=new Date(ms? Number(epoch): Number(epoch)*1000);
  function p(n){ return (n<10?'0':'')+n; }
  return { iso:d.toISOString(), y:d.getUTCFullYear(), mo:p(d.getUTCMonth()+1), da:p(d.getUTCDate()),
    h:p(d.getUTCHours()), mi:p(d.getUTCMinutes()), se:p(d.getUTCSeconds()), wday:d.getUTCDay() };
}
function tsFormat(epoch, ms){
  var f=tsFromEpoch(epoch, ms);
  return f.y+'-'+f.mo+'-'+f.da+' '+f.h+':'+f.mi+':'+f.se;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tsToEpoch:tsToEpoch, tsFromEpoch:tsFromEpoch, tsFormat:tsFormat };
}
if (typeof window !== 'undefined') {
  window.TimestampForgePure = { tsToEpoch:tsToEpoch, tsFromEpoch:tsFromEpoch, tsFormat:tsFormat };
}
